"""Reproduce the original indexed pixel assets without external image tooling."""
import base64
import hashlib
import json
from pathlib import Path
import struct


def image(width, height, frames, palette):
    header = b"ESI1" + bytes((width, height, len(frames), len(palette)))
    colors = b"".join(struct.pack("<HB", color, alpha) for color, alpha in palette)
    pixels = bytes(pixel for frame in frames for pixel in frame)
    return header + struct.pack("<H", 250) + colors + pixels


def build_demo():
    floor = [
        1 if y < 2 else (2 if (x + y) % 2 else 3)
        for y in range(8) for x in range(32)
    ]
    frames = []
    for blink in (False, True):
        frame = []
        for y in range(16):
            for x in range(16):
                color = 0
                if ((3 <= x <= 12 and 4 <= y <= 13)
                    or (4 <= x <= 6 and 1 <= y <= 4)
                    or (10 <= x <= 12 and 1 <= y <= 4)):
                    color = 1
                if y in (7, 8) and x in (6, 10):
                    color = 3 if not blink or y == 8 else 1
                if y == 10 and x in (7, 8, 9):
                    color = 2
                frame.append(color)
        frames.append(frame)
    treat = [
        0, 0, 1, 1, 0, 0,
        0, 1, 2, 2, 1, 0,
        1, 2, 2, 2, 2, 1,
        1, 2, 2, 2, 2, 1,
        0, 1, 2, 2, 1, 0,
        0, 0, 1, 1, 0, 0,
    ]
    assets = {
        "floor": image(32, 8, [floor], [(0, 0), (0x86DA, 255), (0x32AC, 255), (0x2248, 255)]),
        "pet": image(16, 16, frames, [(0, 0), (0xFF96, 255), (0xF284, 255), (0x18C3, 255)]),
        "treat": image(6, 6, [treat], [(0, 0), (0xFEA0, 128), (0xFB00, 255)]),
    }
    return b"ESP1" + bytes([len(assets)]) + b"".join(
        bytes([len(name)]) + name.encode("ascii") + struct.pack("<H", len(data)) + data
        for name, data in assets.items()
    )


def main():
    root = Path(__file__).resolve().parent
    pack = build_demo()
    digest = hashlib.sha256(pack).hexdigest()
    (root / "resources" / "demo.esp").write_bytes(pack)
    chunks = [
        {"offset": offset, "data": base64.b64encode(pack[offset:offset + 256]).decode("ascii")}
        for offset in range(0, len(pack), 256)
    ]
    source = "// Generated by generate_assets.py; Core-owned originals, never JS on Edge.\n"
    source += "export const PACK_BYTES = " + str(len(pack)) + ";\n"
    source += "export const PACK_SHA256 = " + json.dumps(digest) + ";\n"
    source += "export const PACK_CHUNKS = " + json.dumps(chunks, indent=2) + ";\n"
    (root / "src" / "assets.ts").write_text(source, encoding="utf-8")
    print(len(pack), digest)


if __name__ == "__main__":
    main()
